cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

for (const role of ['admin', 'editor', 'viewer']) {
  for (const owner of ['actor', 'other']) {
    for (const archived of [false, true]) {
      for (const visibility of ['visible', 'missing', 'deleted', 'foreign']) {
        const actor = { tenant: 'a', user: 'actor', role };
        const repo = new DocumentRepository([
          {
            id: 'one',
            tenant: visibility === 'foreign' ? 'b' : 'a',
            owner,
            deleted: visibility === 'deleted',
            archived,
          },
          { id: 'untouched', tenant: 'a', owner: 'actor', deleted: false, archived: false },
        ]);
        repo.audit.push({ actor: 'previous', document: 'untouched' });
        const service = new DocumentService(repo);
        const id = visibility === 'missing' ? 'missing' : 'one';
        const before = structuredClone({ documents: repo.documents, audit: repo.audit });
        const context = `${role}, ${owner}, archived=${archived}, ${visibility}`;
        const error = visibility !== 'visible'
          ? 'not found'
          : role === 'admin' || (role === 'editor' && owner === actor.user)
            ? null
            : 'forbidden';

        if (error) {
          assert.throws(() => service.archive(actor, id), new Error(error), context);
          assert.deepEqual({ documents: repo.documents, audit: repo.audit }, before, context);
        } else {
          service.archive(actor, id);
          const expected = structuredClone(before);
          expected.documents[0].archived = true;
          if (!archived) expected.audit.push({ actor: actor.user, document: id });
          assert.deepEqual({ documents: repo.documents, audit: repo.audit }, expected, context);
          service.archive(actor, id);
          assert.deepEqual({ documents: repo.documents, audit: repo.audit }, expected, context);
        }
      }
    }
  }
}
EOF
tsc -p tsconfig.json && node checks/public.cjs

